      af.setX(i, fam);
      c.setHex(bkWall(fam, x, z, B.facade[fam]?.walls ?? [], B.bayPalette));
      if (near.instanceColor) near.setColorAt(i, c);
      if (far?.instanceColor) far.setColorAt(i, c.multiplyScalar(0.92));
