          if ((fn == 3 || fn == 5) && vBPos.y - vBBase < 4.3) { litK = ${f1(B.shopLit)}; lit = vec3(1.0, 0.6, 0.26); gain = ${f1(B.shopGain)}; }   // tầng trệt cửa hàng sáng ấm
          float on = step(1.0 - litK, h);
          totalEmissiveRadiance += wm * on * lit * uNight * gain;'''
