import { pathToFileURL } from 'node:url';
import fs from 'node:fs/promises';
import path from 'node:path';
const ROOT = 'D:/2026 - Tuan/danang-vite';
const { chromium } = await import(pathToFileURL(ROOT + '/node_modules/playwright/index.mjs').href);
const { serveDir, openApp, frames } = await import(pathToFileURL(ROOT + '/tests/lib.mjs').href);
const out = process.argv[2], q = process.argv[3] && !process.argv[3].startsWith('--') ? process.argv[3] : '';
await fs.mkdir(out, { recursive: true });
const srv = await serveDir(ROOT + '/dist/');
const args = ['--ignore-gpu-blocklist', '--enable-gpu', '--disable-gpu-vsync', '--disable-frame-rate-limit', '--use-angle=d3d11'];
const browser = await chromium.launch({ headless: true, args });
const { page, errors } = await openApp(browser, srv.url + (q ? '?' + q : ''), { width: 1280, height: 720 });
const r = await page.evaluate(() => {
  const A = window.__app, S = A.buildings.shaped(), st = A.buildings.state();
  const med = (a) => { const s = [...a].sort((x, y) => x - y); return s.length ? s[s.length >> 1] : null; };
  const bank = (sg) => { const L = S.filter((b) => Math.sign(b.x) === sg), fam = {}; for (const b of L) fam[b.fam] = (fam[b.fam] || 0) + 1;
    const hb = (a) => ({ min: Math.min(...a).toFixed(1), med: med(a).toFixed(1), max: Math.max(...a).toFixed(1) });
    const bins = { '<20': 0, '20-45': 0, '45-75': 0, '>=75': 0 }; for (const b of L) bins[b.h < 20 ? '<20' : b.h < 45 ? '20-45' : b.h < 75 ? '45-75' : '>=75']++;
    const bins0 = { '<20': 0, '20-45': 0, '45-75': 0, '>=75': 0 }; for (const b of L) bins0[b.h0 < 20 ? '<20' : b.h0 < 45 ? '20-45' : b.h0 < 75 ? '45-75' : '>=75']++;
    return { n: L.length, fam, before: hb(L.map((b) => b.h0)), after: hb(L.map((b) => b.h)), bins0, bins, raised: L.filter((b) => b.h > b.h0 + 1e-6).length, under9: L.filter((b) => b.h < 9).length };
  };
  const kit = st ? { counts: st.counts, east: st.east, meshes: st.meshes.map((m) => `${m.name}:${m.count}`) } : null;
  let bkMeshes = 0; A.scene.traverse((o) => { if (/^bk-fam/.test(o.name)) bkMeshes++; });
  return { west: bank(-1), east: bank(1), kit, bkMeshes, ads: A.riverfront.billboards.counts, programs: A.renderer.info.programs.length };
});
console.log(JSON.stringify(r, null, 1));
const setCam = (pos, target) => page.evaluate(([p, t]) => { const A = window.__app; A.cam.mode = 'orbit'; A.controls.enabled = true; A.controls.maxPolarAngle = Math.PI * 0.97; A.camera.position.set(...p); A.controls.target.set(...t); A.controls.update(); }, [pos, target]);
const setNight = (n) => page.evaluate((n) => { const d = window.__app.dayNight; d.target = d.night = n; }, n);
const stats = () => page.evaluate(() => { const R = window.__app.renderer; R.info.reset(); R.render(window.__app.scene, window.__app.camera); return `${R.info.render.calls} lệnh vẽ, ${R.info.render.triangles} tam giác`; });
const SHOTS = {
  // đi dọc phố sau hàng nhà đầu bờ Tây (chuyển động ngắn), nhìn chéo vào mặt nhà quay ra sông
  tayA: [[-300, 22, -260], [-390, 14, -330]], tayB: [[-300, 22, -250], [-390, 14, -320]], tayC: [[-300, 22, -240], [-390, 14, -310]], tayD: [[-300, 22, -230], [-390, 14, -300]],
  dongA: [[300, 22, 300], [390, 14, 230]], dongB: [[300, 22, 310], [390, 14, 240]], dongC: [[300, 22, 320], [390, 14, 250]],
  // qua ngưỡng kitNear 600 m / kitFar 1400 m: lùi camera
  lodA: [[-100, 60, -520], [-420, 20, -560]], lodB: [[60, 70, -520], [-420, 20, -560]], lodC: [[200, 80, -520], [-420, 20, -560]],
  farA: [[900, 120, -500], [-420, 20, -560]], farB: [[1000, 120, -500], [-420, 20, -560]],
  bayDong: [[60, 50, 700], [420, 20, 640]]
};
const want = (process.argv.find((a) => a.startsWith('--shots=')) || '').slice(8).split(',').filter(Boolean);
for (const night of [0, 1]) {
  if (process.argv.includes('--nostats')) break;
  await setNight(night);
  for (const [k, [p, t]] of Object.entries(SHOTS)) {
    if (want.length && !want.includes(k)) continue;
    await setCam(p, t); await frames(page, 4);
    const s = await stats(); await frames(page, 2);
    await page.screenshot({ path: path.join(out, `${k}-${night ? 'dem' : 'ngay'}.png`) });
    console.log(k, night ? 'đêm' : 'ngày', s);
    if (night && !want.length && !k.startsWith('bay')) continue;
  }
}
console.log('lỗi console:', errors.length, errors.slice(0, 5));
await browser.close(); srv.close();
EOF
